#[cfg(test)]
mod logon_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_logon_codec() {
        let original = Logon {
            sender_comp_id: "a".repeat(32),
            target_comp_id: "a".repeat(32),
            heart_bt_int: 1234,
            prtcl_version: "a".repeat(8),
            trade_date: 123456,
            q_size: 123456,
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let mut bytes = buf.freeze();

        let decoded = Logon::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
    }
}
